302|xmlFuzzReadEntities(void) {
303|    size_t num = 0;
304|
305|    while (1) {
306|        const char *url, *entity;
307|        size_t entitySize;
308|        xmlFuzzEntityInfo *entityInfo;
309|
310|        url = xmlFuzzReadString(NULL);
311|        if (url == NULL) break;
312|
313|        entity = xmlFuzzReadString(&entitySize);
