320|            entityInfo->data = entity;
321|            entityInfo->size = entitySize;
322|
323|            xmlHashAddEntry(fuzzData.entities, (xmlChar *)url, entityInfo);
324|
325|            if (num == 0) {
326|                fuzzData.mainUrl = url;
327|                fuzzData.mainEntity = entityInfo;
