399|xmlSlurpFile(const char *path, size_t *sizeRet) {
400|    FILE *file;
401|    struct stat statbuf;
402|    char *data;
403|    size_t size;
404|
405|    if ((stat(path, &statbuf) != 0) || (!S_ISREG(statbuf.st_mode)))
406|        return(NULL);
407|    size = statbuf.st_size;
408|    file = fopen(path, "rb");
409|    if (file == NULL)
410|        return(NULL);
411|    data = xmlMalloc(size + 1);
412|    if (data != NULL) {
413|        if (fread(data, 1, size, file) != size) {
414|            xmlFree(data);
415|            data = NULL;
416|        } else {
417|            data[size] = 0;
418|            if (sizeRet != NULL)
419|                *sizeRet = size;
420|        }
421|    }
422|    fclose(file);
423|
424|    return(data);
