10447|int
10448|xmlParseDocument(xmlParserCtxtPtr ctxt) {
10449|    if ((ctxt == NULL) || (ctxt->input == NULL))
10450|        return(-1);
10451|
10452|    GROW;
10453|
10454|    /*
10455|     * SAX: detecting the level.
10456|     */
10457|    xmlCtxtInitializeLate(ctxt);
10458|
10459|    /*
10460|     * Document locator is unused. Only for backward compatibility.
10461|     */
10462|    if ((ctxt->sax) && (ctxt->sax->setDocumentLocator)) {
10463|        xmlSAXLocator copy = xmlDefaultSAXLocator;
10464|        ctxt->sax->setDocumentLocator(ctxt->userData, &copy);
10465|    }
10466|
10467|    xmlDetectEncoding(ctxt);
10468|
10469|    if (CUR == 0) {
10470|	xmlFatalErr(ctxt, XML_ERR_DOCUMENT_EMPTY, NULL);
10471|	return(-1);
10472|    }
10473|
10474|    GROW;
10475|    if ((CMP5(CUR_PTR, '<', '?', 'x', 'm', 'l')) && (IS_BLANK_CH(NXT(5)))) {
10476|
10477|	/*
10478|	 * Note that we will switch encoding on the fly.
10479|	 */
10480|	xmlParseXMLDecl(ctxt);
10481|	SKIP_BLANKS;
10482|    } else {
10483|	ctxt->version = xmlCharStrdup(XML_DEFAULT_VERSION);
10484|        if (ctxt->version == NULL) {
10485|            xmlErrMemory(ctxt);
10486|            return(-1);
10487|        }
10488|    }
10489|    if ((ctxt->sax) && (ctxt->sax->startDocument) && (!ctxt->disableSAX))
10490|        ctxt->sax->startDocument(ctxt->userData);
10491|    if ((ctxt->myDoc != NULL) && (ctxt->input != NULL) &&
10492|        (ctxt->input->buf != NULL) && (ctxt->input->buf->compressed >= 0)) {
10493|	ctxt->myDoc->compression = ctxt->input->buf->compressed;
10494|    }
10495|
10496|    /*
10497|     * The Misc part of the Prolog
10498|     */
10499|    xmlParseMisc(ctxt);
10500|
10501|    /*
10502|     * Then possibly doc type declaration(s) and more Misc
10503|     * (doctypedecl Misc*)?
10504|     */
10505|    GROW;
10506|    if (CMP9(CUR_PTR, '<', '!', 'D', 'O', 'C', 'T', 'Y', 'P', 'E')) {
10507|
10508|	ctxt->inSubset = 1;
10509|	xmlParseDocTypeDecl(ctxt);
10510|	if (RAW == '[') {
10511|	    xmlParseInternalSubset(ctxt);
10512|	}
10513|
10514|	/*
10515|	 * Create and update the external subset.
10516|	 */
10517|	ctxt->inSubset = 2;
10518|	if ((ctxt->sax != NULL) && (ctxt->sax->externalSubset != NULL) &&
10519|	    (!ctxt->disableSAX))
10520|	    ctxt->sax->externalSubset(ctxt->userData, ctxt->intSubName,
10521|	                              ctxt->extSubSystem, ctxt->extSubURI);
10522|	ctxt->inSubset = 0;
10523|
10524|        xmlCleanSpecialAttr(ctxt);
10525|
10526|	xmlParseMisc(ctxt);
10527|    }
10528|
10529|    /*
10530|     * Time to start parsing the tree itself
10531|     */
10532|    GROW;
10533|    if (RAW != '<') {
10534|	xmlFatalErrMsg(ctxt, XML_ERR_DOCUMENT_EMPTY,
10535|		       "Start tag expected, '<' not found\n");
10536|    } else {
10537|	xmlParseElement(ctxt);
10538|
10539|	/*
10540|	 * The Misc part at the end
10541|	 */
10542|	xmlParseMisc(ctxt);
10543|
10544|        if (ctxt->input->cur < ctxt->input->end) {
10545|            if (ctxt->errNo == XML_ERR_OK)
10546|	        xmlFatalErr(ctxt, XML_ERR_DOCUMENT_END, NULL);
10547|        } else if ((ctxt->input->buf != NULL) &&
10548|                   (ctxt->input->buf->encoder != NULL) &&
10549|                   (!xmlBufIsEmpty(ctxt->input->buf->raw))) {
10550|            xmlFatalErrMsg(ctxt, XML_ERR_INVALID_CHAR,
10551|                           "Truncated multi-byte sequence at EOF\n");
10552|        }
10553|    }
10554|
10555|    ctxt->instate = XML_PARSER_EOF;
10556|    xmlFinishDocument(ctxt);
10557|
10558|    if (! ctxt->wellFormed) {
10559|	ctxt->valid = 0;
10560|	return(-1);
10561|    }
10562|
10563|    return(0);
10564|}

