8092|xmlParseDocTypeDecl(xmlParserCtxtPtr ctxt) {
8093|    const xmlChar *name = NULL;
8094|    xmlChar *ExternalID = NULL;
8095|    xmlChar *URI = NULL;
8096|
8097|    /*
8098|     * We know that '<!DOCTYPE' has been detected.
8099|     */
8100|    SKIP(9);
8101|
8102|    SKIP_BLANKS;
8103|
8104|    /*
8105|     * Parse the DOCTYPE name.
8106|     */
8107|    name = xmlParseName(ctxt);
8108|    if (name == NULL) {
8109|	xmlFatalErrMsg(ctxt, XML_ERR_NAME_REQUIRED,
8110|		       "xmlParseDocTypeDecl : no DOCTYPE name !\n");
8111|    }
8112|    ctxt->intSubName = name;
8113|
8114|    SKIP_BLANKS;
8115|
8116|    /*
8117|     * Check for SystemID and ExternalID
8118|     */
8119|    URI = xmlParseExternalID(ctxt, &ExternalID, 1);
8120|
8121|    if ((URI != NULL) || (ExternalID != NULL)) {
8122|        ctxt->hasExternalSubset = 1;
8123|    }
8124|    ctxt->extSubURI = URI;
8125|    ctxt->extSubSystem = ExternalID;
8126|
8127|    SKIP_BLANKS;
8128|
8129|    /*
8130|     * Create and update the internal subset.
8131|     */
8132|    if ((ctxt->sax != NULL) && (ctxt->sax->internalSubset != NULL) &&
8133|	(!ctxt->disableSAX))
8134|	ctxt->sax->internalSubset(ctxt->userData, name, ExternalID, URI);
8135|
8136|    /*
8137|     * Is there any internal subset declarations ?
8138|     * they are handled separately in xmlParseInternalSubset()
8139|     */
8140|    if (RAW == '[')
8141|	return;
8142|
8143|    /*
8144|     * We should be at the end of the DOCTYPE declaration.
8145|     */
8146|    if (RAW != '>') {
8147|	xmlFatalErr(ctxt, XML_ERR_DOCTYPE_NOT_FINISHED, NULL);
8148|    }
8149|    NEXT;
