7250|xmlParseExternalSubset(xmlParserCtxtPtr ctxt, const xmlChar *ExternalID,
7251|                       const xmlChar *SystemID) {
7252|    xmlCtxtInitializeLate(ctxt);
7253|
7254|    xmlDetectEncoding(ctxt);
7255|
7256|    if (CMP5(CUR_PTR, '<', '?', 'x', 'm', 'l')) {
7257|	xmlParseTextDecl(ctxt);
7258|    }
7259|    if (ctxt->myDoc == NULL) {
7260|        ctxt->myDoc = xmlNewDoc(BAD_CAST "1.0");
7261|	if (ctxt->myDoc == NULL) {
7262|	    xmlErrMemory(ctxt);
7263|	    return;
7264|	}
7265|	ctxt->myDoc->properties = XML_DOC_INTERNAL;
7266|    }
7267|    if ((ctxt->myDoc != NULL) && (ctxt->myDoc->intSubset == NULL) &&
7268|        (xmlCreateIntSubset(ctxt->myDoc, NULL, ExternalID, SystemID) == NULL)) {
7269|        xmlErrMemory(ctxt);
7270|    }
7271|
7272|    ctxt->inSubset = 2;
7273|
7274|    SKIP_BLANKS_PE;
7275|    while ((PARSER_STOPPED(ctxt) == 0) && (RAW != 0)) {
7276|	GROW;
7277|        if ((RAW == '<') && (NXT(1) == '!') && (NXT(2) == '[')) {
