1465|    }
1466|    if ((reader->node != NULL) && (reader->node->type == XML_XINCLUDE_END)) {
1467|        reader->in_xinclude--;
1468|	goto get_next_node;
1469|    }
1470|#endif
1471|    /*
1472|     * Handle entities enter and exit when in entity replacement mode
1473|     */
1474|    if ((reader->node != NULL) &&
1475|	(reader->node->type == XML_ENTITY_REF_NODE) &&
1476|	(reader->ctxt != NULL) && (reader->ctxt->replaceEntities == 1)) {
1477|	if ((reader->node->children != NULL) &&
1478|	    (reader->node->children->type == XML_ENTITY_DECL) &&
1479|	    (reader->node->children->children != NULL)) {
1480|	    if (xmlTextReaderEntPush(reader, reader->node) < 0)
1481|                goto get_next_node;
