1483|	}
1484|#ifdef LIBXML_REGEXP_ENABLED
1485|    } else if ((reader->node != NULL) &&
1486|	       (reader->node->type == XML_ENTITY_REF_NODE) &&
1487|	       (reader->ctxt != NULL) && (reader->validate)) {
1488|	xmlTextReaderValidateEntity(reader);
