1491|    if ((reader->node != NULL) &&
1492|	(reader->node->type == XML_ENTITY_DECL) &&
1493|	(reader->ent != NULL) && (reader->ent->children == reader->node)) {
1494|	reader->node = xmlTextReaderEntPop(reader);
