1528|        (reader->xsdValidErrors == 0) &&
1529|	(reader->xsdValidCtxt != NULL)) {
1530|	reader->xsdValidErrors = !xmlSchemaIsValid(reader->xsdValidCtxt);
1531|    }
1532|#endif /* LIBXML_PATTERN_ENABLED */
