159|/**
160| * xmlCtxtErrIO:
161| * @ctxt:  parser context
162| * @code:  xmlParserErrors code
163| * @uri:  filename or URI (optional)
164| *
165| * If filename is empty, use the one from context input if available.
166| *
167| * Report an IO error to the parser context.
168| */
169|void
170|xmlCtxtErrIO(xmlParserCtxtPtr ctxt, int code, const char *uri)
171|{
172|    const char *errstr, *msg, *str1, *str2;
173|    xmlErrorLevel level;
174|
175|    if (ctxt == NULL)
176|        return;
177|
178|    if ((code == XML_IO_ENOENT) ||
179|        (code == XML_IO_NETWORK_ATTEMPT) ||
180|        (code == XML_IO_UNKNOWN)) {
181|        if (ctxt->validate == 0)
182|            level = XML_ERR_WARNING;
183|        else
184|            level = XML_ERR_ERROR;
185|    } else {
186|        level = XML_ERR_FATAL;
187|    }
188|
189|    errstr = xmlErrString(code);
190|
191|    if (uri == NULL) {
192|        msg = "%s\n";
193|        str1 = errstr;
194|        str2 = NULL;
195|    } else {
196|        msg = "failed to load \"%s\": %s\n";
197|        str1 = uri;
198|        str2 = errstr;
199|    }
200|
201|    xmlCtxtErr(ctxt, NULL, XML_FROM_IO, code, level,
202|               (const xmlChar *) uri, NULL, NULL, 0,
203|               msg, str1, str2);
204|}
