206|void
207|xmlCtxtVErr(xmlParserCtxtPtr ctxt, xmlNodePtr node, xmlErrorDomain domain,
208|            xmlParserErrors code, xmlErrorLevel level,
209|            const xmlChar *str1, const xmlChar *str2, const xmlChar *str3,
210|            int int1, const char *msg, va_list ap)
211|{
212|    xmlStructuredErrorFunc schannel = NULL;
213|    xmlGenericErrorFunc channel = NULL;
214|    void *data = NULL;
215|    const char *file = NULL;
216|    int line = 0;
217|    int col = 0;
218|    int res;
219|
220|    if (PARSER_STOPPED(ctxt))
221|	return;
222|
223|    if (code == XML_ERR_NO_MEMORY) {
224|        xmlCtxtErrMemory(ctxt);
225|        return;
226|    }
227|
228|    if (level == XML_ERR_WARNING) {
229|        if (ctxt->nbWarnings >= XML_MAX_ERRORS)
230|            return;
231|        ctxt->nbWarnings += 1;
232|    } else {
233|        if (ctxt->nbErrors >= XML_MAX_ERRORS)
234|            return;
235|        ctxt->nbErrors += 1;
236|    }
237|
238|    if (((ctxt->options & XML_PARSE_NOERROR) == 0) &&
239|        ((level != XML_ERR_WARNING) ||
240|         ((ctxt->options & XML_PARSE_NOWARNING) == 0))) {
241|        if (ctxt->errorHandler) {
242|            schannel = ctxt->errorHandler;
243|            data = ctxt->errorCtxt;
244|        } else if ((ctxt->sax->initialized == XML_SAX2_MAGIC) &&
245|            (ctxt->sax->serror != NULL)) {
246|            schannel = ctxt->sax->serror;
247|            data = ctxt->userData;
248|        } else if ((domain == XML_FROM_VALID) || (domain == XML_FROM_DTD)) {
249|            if (level == XML_ERR_WARNING)
250|                channel = ctxt->vctxt.warning;
251|            else
252|                channel = ctxt->vctxt.error;
253|            data = ctxt->vctxt.userData;
254|        } else {
255|            if (level == XML_ERR_WARNING)
256|                channel = ctxt->sax->warning;
257|            else
258|                channel = ctxt->sax->error;
259|            data = ctxt->userData;
260|        }
261|    }
262|
263|    if (ctxt->input != NULL) {
264|        xmlParserInputPtr input = ctxt->input;
265|
266|        if ((input->filename == NULL) &&
267|            (ctxt->inputNr > 1)) {
268|            input = ctxt->inputTab[ctxt->inputNr - 2];
269|        }
270|        file = input->filename;
271|        line = input->line;
272|        col = input->col;
273|    }
274|
275|    res = xmlVRaiseError(schannel, channel, data, ctxt, node, domain, code,
276|                         level, file, line, (const char *) str1,
277|                         (const char *) str2, (const char *) str3, int1, col,
278|                         msg, ap);
279|
280|    if (res < 0) {
281|        xmlCtxtErrMemory(ctxt);
282|        return;
283|    }
284|
285|    if (level >= XML_ERR_ERROR)
286|        ctxt->errNo = code;
287|    if (level == XML_ERR_FATAL) {
288|        ctxt->wellFormed = 0;
289|        if (ctxt->recovery == 0)
290|            ctxt->disableSAX = 1;
291|    }
292|
293|    return;
294|}
