393|/**
394| * xmlParserGrow:
395| * @ctxt:  an XML parser context
396| *
397| * Grow the input buffer.
398| *
399| * Returns the number of bytes read or -1 in case of error.
400| */
401|int
402|xmlParserGrow(xmlParserCtxtPtr ctxt) {
403|    xmlParserInputPtr in = ctxt->input;
404|    xmlParserInputBufferPtr buf = in->buf;
405|    size_t curEnd = in->end - in->cur;
406|    size_t curBase = in->cur - in->base;
407|    size_t maxLength = (ctxt->options & XML_PARSE_HUGE) ?
408|                       XML_MAX_HUGE_LENGTH :
409|                       XML_MAX_LOOKUP_LIMIT;
410|    int ret;
411|
412|    if (buf == NULL)
413|        return(0);
414|    /* Don't grow push parser buffer. */
415|    if (PARSER_PROGRESSIVE(ctxt))
416|        return(0);
417|    /* Don't grow memory buffers. */
418|    if ((buf->encoder == NULL) && (buf->readcallback == NULL))
419|        return(0);
420|    if (buf->error != 0)
421|        return(-1);
422|
423|    if (curBase > maxLength) {
424|        xmlFatalErr(ctxt, XML_ERR_RESOURCE_LIMIT,
425|                    "Buffer size limit exceeded, try XML_PARSE_HUGE\n");
426|        xmlHaltParser(ctxt);
427|	return(-1);
428|    }
429|
430|    if (curEnd >= INPUT_CHUNK)
431|        return(0);
432|
433|    ret = xmlParserInputBufferGrow(buf, INPUT_CHUNK);
434|    xmlBufUpdateInput(buf->buffer, in, curBase);
435|
436|    if (ret < 0) {
437|        xmlCtxtErrIO(ctxt, buf->error, NULL);
438|    }
439|
440|    return(ret);
441|}
