443|/**
444| * xmlParserInputGrow:
445| * @in:  an XML parser input
446| * @len:  an indicative size for the lookahead
447| *
448| * DEPRECATED: Don't use.
449| *
450| * This function increase the input for the parser. It tries to
451| * preserve pointers to the input buffer, and keep already read data
452| *
453| * Returns the amount of char read, or -1 in case of error, 0 indicate the
454| * end of this entity
455| */
456|int
457|xmlParserInputGrow(xmlParserInputPtr in, int len) {
458|    int ret;
459|    size_t indx;
460|
461|    if ((in == NULL) || (len < 0)) return(-1);
462|    if (in->buf == NULL) return(-1);
463|    if (in->base == NULL) return(-1);
464|    if (in->cur == NULL) return(-1);
465|    if (in->buf->buffer == NULL) return(-1);
466|
467|    /* Don't grow memory buffers. */
468|    if ((in->buf->encoder == NULL) && (in->buf->readcallback == NULL))
469|        return(0);
470|
471|    indx = in->cur - in->base;
472|    if (xmlBufUse(in->buf->buffer) > (unsigned int) indx + INPUT_CHUNK) {
473|        return(0);
474|    }
475|    ret = xmlParserInputBufferGrow(in->buf, len);
476|
477|    in->base = xmlBufContent(in->buf->buffer);
478|    if (in->base == NULL) {
479|        in->base = BAD_CAST "";
480|        in->cur = in->base;
481|        in->end = in->base;
482|        return(-1);
483|    }
484|    in->cur = in->base + indx;
485|    in->end = xmlBufEnd(in->buf->buffer);
486|
487|    return(ret);
488|}
