490|/**
491| * xmlParserShrink:
492| * @ctxt:  an XML parser context
493| *
494| * Shrink the input buffer.
495| */
496|void
497|xmlParserShrink(xmlParserCtxtPtr ctxt) {
498|    xmlParserInputPtr in = ctxt->input;
499|    xmlParserInputBufferPtr buf = in->buf;
500|    size_t used;
501|
502|    if (buf == NULL)
503|        return;
504|    /* Don't shrink pull parser memory buffers. */
505|    if ((!PARSER_PROGRESSIVE(ctxt)) &&
506|        (buf->encoder == NULL) &&
507|        (buf->readcallback == NULL))
508|        return;
509|
510|    used = in->cur - in->base;
511|    /*
512|     * Do not shrink on large buffers whose only a tiny fraction
513|     * was consumed
514|     */
515|    if (used > INPUT_CHUNK) {
516|	size_t res = xmlBufShrink(buf->buffer, used - LINE_LEN);
517|
518|	if (res > 0) {
519|            used -= res;
520|            if ((res > ULONG_MAX) ||
521|                (in->consumed > ULONG_MAX - (unsigned long)res))
522|                in->consumed = ULONG_MAX;
523|            else
524|                in->consumed += res;
525|	}
526|    }
527|
528|    xmlBufUpdateInput(buf->buffer, in, used);
529|}
530|
531|/**
532| * xmlParserInputShrink:
533| * @in:  an XML parser input
534| *
535| * DEPRECATED: Don't use.
536| *
537| * This function removes used input for the parser.
538| */
539|void
540|xmlParserInputShrink(xmlParserInputPtr in) {
541|    size_t used;
542|    size_t ret;
543|
544|    if (in == NULL) return;
545|    if (in->buf == NULL) return;
546|    if (in->base == NULL) return;
547|    if (in->cur == NULL) return;
548|    if (in->buf->buffer == NULL) return;
549|
550|    used = in->cur - in->base;
551|    /*
552|     * Do not shrink on large buffers whose only a tiny fraction
553|     * was consumed
554|     */
555|    if (used > INPUT_CHUNK) {
556|	ret = xmlBufShrink(in->buf->buffer, used - LINE_LEN);
557|	if (ret > 0) {
558|            used -= ret;
559|            if ((ret > ULONG_MAX) ||
560|                (in->consumed > ULONG_MAX - (unsigned long)ret))
561|                in->consumed = ULONG_MAX;
562|            else
563|                in->consumed += ret;
