589|/**
590| * xmlNextChar:
591| * @ctxt:  the XML parser context
592| *
593| * DEPRECATED: Internal function, do not use.
594| *
595| * Skip to the next char input char.
596| */
597|
598|void
599|xmlNextChar(xmlParserCtxtPtr ctxt)
600|{
601|    const unsigned char *cur;
602|    size_t avail;
603|    int c;
604|
605|    if ((ctxt == NULL) || (ctxt->input == NULL))
606|        return;
607|
608|    avail = ctxt->input->end - ctxt->input->cur;
609|
610|    if (avail < INPUT_CHUNK) {
611|        xmlParserGrow(ctxt);
612|        if (ctxt->input->cur >= ctxt->input->end)
613|            return;
614|        avail = ctxt->input->end - ctxt->input->cur;
615|    }
616|
617|    cur = ctxt->input->cur;
618|    c = *cur;
619|
620|    if (c < 0x80) {
621|        if (c == '\n') {
622|            ctxt->input->cur++;
623|            ctxt->input->line++;
624|            ctxt->input->col = 1;
625|        } else if (c == '\r') {
626|            /*
627|             *   2.11 End-of-Line Handling
628|             *   the literal two-character sequence "#xD#xA" or a standalone
629|             *   literal #xD, an XML processor must pass to the application
630|             *   the single character #xA.
631|             */
632|            ctxt->input->cur += ((cur[1] == '\n') ? 2 : 1);
633|            ctxt->input->line++;
634|            ctxt->input->col = 1;
635|            return;
636|        } else {
637|            ctxt->input->cur++;
638|            ctxt->input->col++;
639|        }
640|    } else {
641|        ctxt->input->col++;
642|
643|        if ((avail < 2) || (cur[1] & 0xc0) != 0x80)
644|            goto encoding_error;
645|
646|        if (c < 0xe0) {
647|            /* 2-byte code */
648|            if (c < 0xc2)
649|                goto encoding_error;
650|            ctxt->input->cur += 2;
651|        } else {
652|            unsigned int val = (c << 8) | cur[1];
653|
654|            if ((avail < 3) || (cur[2] & 0xc0) != 0x80)
655|                goto encoding_error;
656|
657|            if (c < 0xf0) {
658|                /* 3-byte code */
659|                if ((val < 0xe0a0) || ((val >= 0xeda0) && (val < 0xee00)))
660|                    goto encoding_error;
661|                ctxt->input->cur += 3;
662|            } else {
663|                if ((avail < 4) || ((cur[3] & 0xc0) != 0x80))
664|                    goto encoding_error;
665|
666|                /* 4-byte code */
667|                if ((val < 0xf090) || (val >= 0xf490))
668|                    goto encoding_error;
669|                ctxt->input->cur += 4;
670|            }
671|        }
672|    }
673|
674|    return;
675|
676|encoding_error:
677|    /* Only report the first error */
678|    if ((ctxt->input->flags & XML_INPUT_ENCODING_ERROR) == 0) {
679|        xmlCtxtErrIO(ctxt, XML_ERR_INVALID_ENCODING, NULL);
680|        ctxt->input->flags |= XML_INPUT_ENCODING_ERROR;
681|    }
682|    ctxt->input->cur++;
683|    return;
