686|/**
687| * xmlCurrentChar:
688| * @ctxt:  the XML parser context
689| * @len:  pointer to the length of the char read
690| *
691| * DEPRECATED: Internal function, do not use.
692| *
693| * The current char value, if using UTF-8 this may actually span multiple
694| * bytes in the input buffer. Implement the end of line normalization:
695| * 2.11 End-of-Line Handling
696| * Wherever an external parsed entity or the literal entity value
697| * of an internal parsed entity contains either the literal two-character
698| * sequence "#xD#xA" or a standalone literal #xD, an XML processor
699| * must pass to the application the single character #xA.
700| * This behavior can conveniently be produced by normalizing all
701| * line breaks to #xA on input, before parsing.)
702| *
703| * Returns the current char value and its length
704| */
705|
706|int
707|xmlCurrentChar(xmlParserCtxtPtr ctxt, int *len) {
708|    const unsigned char *cur;
709|    size_t avail;
710|    int c;
711|
712|    if ((ctxt == NULL) || (len == NULL) || (ctxt->input == NULL)) return(0);
713|
714|    avail = ctxt->input->end - ctxt->input->cur;
715|
716|    if (avail < INPUT_CHUNK) {
717|        xmlParserGrow(ctxt);
718|        avail = ctxt->input->end - ctxt->input->cur;
719|    }
720|
721|    cur = ctxt->input->cur;
722|    c = *cur;
723|
724|    if (c < 0x80) {
725|	/* 1-byte code */
726|        if (c < 0x20) {
727|            /*
728|             *   2.11 End-of-Line Handling
729|             *   the literal two-character sequence "#xD#xA" or a standalone
730|             *   literal #xD, an XML processor must pass to the application
731|             *   the single character #xA.
732|             */
733|            if (c == '\r') {
734|                /*
735|                 * TODO: This function shouldn't change the 'cur' pointer
736|                 * as side effect, but the NEXTL macro in parser.c relies
737|                 * on this behavior when incrementing line numbers.
738|                 */
739|                if (cur[1] == '\n')
740|                    ctxt->input->cur++;
741|                *len = 1;
742|                c = '\n';
743|            } else if (c == 0) {
744|                if (ctxt->input->cur >= ctxt->input->end) {
745|                    *len = 0;
746|                } else {
747|                    *len = 1;
748|                    /*
749|                     * TODO: Null bytes should be handled by callers,
750|                     * but this can be tricky.
751|                     */
752|                    xmlFatalErr(ctxt, XML_ERR_INVALID_CHAR,
753|                            "Char 0x0 out of allowed range\n");
754|                }
755|            } else {
756|                *len = 1;
757|            }
758|        } else {
759|            *len = 1;
760|        }
761|
762|        return(c);
763|    } else {
764|        int val;
765|
766|        if (avail < 2)
767|            goto incomplete_sequence;
768|        if ((cur[1] & 0xc0) != 0x80)
769|            goto encoding_error;
770|
771|        if (c < 0xe0) {
772|            /* 2-byte code */
773|            if (c < 0xc2)
774|                goto encoding_error;
775|            val = (c & 0x1f) << 6;
776|            val |= cur[1] & 0x3f;
777|            *len = 2;
778|        } else {
779|            if (avail < 3)
780|                goto incomplete_sequence;
781|            if ((cur[2] & 0xc0) != 0x80)
782|                goto encoding_error;
783|
784|            if (c < 0xf0) {
785|                /* 3-byte code */
786|                val = (c & 0xf) << 12;
787|                val |= (cur[1] & 0x3f) << 6;
788|                val |= cur[2] & 0x3f;
789|                if ((val < 0x800) || ((val >= 0xd800) && (val < 0xe000)))
790|                    goto encoding_error;
791|                *len = 3;
792|            } else {
793|                if (avail < 4)
794|                    goto incomplete_sequence;
795|                if ((cur[3] & 0xc0) != 0x80)
796|                    goto encoding_error;
797|
798|                /* 4-byte code */
799|                val = (c & 0x0f) << 18;
800|                val |= (cur[1] & 0x3f) << 12;
801|                val |= (cur[2] & 0x3f) << 6;
802|                val |= cur[3] & 0x3f;
803|                if ((val < 0x10000) || (val >= 0x110000))
804|                    goto encoding_error;
805|                *len = 4;
806|            }
807|        }
808|
809|        return(val);
810|    }
811|
812|encoding_error:
813|    /* Only report the first error */
814|    if ((ctxt->input->flags & XML_INPUT_ENCODING_ERROR) == 0) {
815|        xmlCtxtErrIO(ctxt, XML_ERR_INVALID_ENCODING, NULL);
816|        ctxt->input->flags |= XML_INPUT_ENCODING_ERROR;
817|    }
818|    *len = 1;
819|    return(0xFFFD); /* U+FFFD Replacement Character */
820|
821|incomplete_sequence:
822|    /*
823|     * An encoding problem may arise from a truncated input buffer
824|     * splitting a character in the middle. In that case do not raise
825|     * an error but return 0. This should only happen when push parsing
826|     * char data.
827|     */
828|    *len = 0;
829|    return(0);
