861|/**
862| * xmlCopyCharMultiByte:
863| * @out:  pointer to an array of xmlChar
864| * @val:  the char value
865| *
866| * append the char value in the array
867| *
868| * Returns the number of xmlChar written
869| */
870|int
871|xmlCopyCharMultiByte(xmlChar *out, int val) {
872|    if ((out == NULL) || (val < 0)) return(0);
873|    /*
874|     * We are supposed to handle UTF8, check it's valid
875|     * From rfc2044: encoding of the Unicode values on UTF-8:
876|     *
877|     * UCS-4 range (hex.)           UTF-8 octet sequence (binary)
878|     * 0000 0000-0000 007F   0xxxxxxx
879|     * 0000 0080-0000 07FF   110xxxxx 10xxxxxx
880|     * 0000 0800-0000 FFFF   1110xxxx 10xxxxxx 10xxxxxx
881|     */
882|    if  (val >= 0x80) {
883|	xmlChar *savedout = out;
884|	int bits;
885|	if (val <   0x800) { *out++= (val >>  6) | 0xC0;  bits=  0; }
886|	else if (val < 0x10000) { *out++= (val >> 12) | 0xE0;  bits=  6;}
887|	else if (val < 0x110000)  { *out++= (val >> 18) | 0xF0;  bits=  12; }
888|	else {
889|#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
890|            fprintf(stderr, "xmlCopyCharMultiByte: codepoint out of range\n");
891|            abort();
892|#endif
893|	    return(0);
894|	}
895|	for ( ; bits >= 0; bits-= 6)
896|	    *out++= ((val >> bits) & 0x3F) | 0x80 ;
897|	return (out - savedout);
898|    }
899|    *out = val;
900|    return 1;
901|}
902|
903|/**
904| * xmlCopyChar:
905| * @len:  Ignored, compatibility
906| * @out:  pointer to an array of xmlChar
907| * @val:  the char value
908| *
909| * append the char value in the array
910| *
911| * Returns the number of xmlChar written
912| */
913|
914|int
915|xmlCopyChar(int len ATTRIBUTE_UNUSED, xmlChar *out, int val) {
916|    if ((out == NULL) || (val < 0)) return(0);
917|    /* the len parameter is ignored */
918|    if  (val >= 0x80) {
919|	return(xmlCopyCharMultiByte (out, val));
920|    }
921|    *out = val;
922|    return 1;
923|}
