925|/************************************************************************
926| *									*
927| *		Commodity functions to switch encodings			*
928| *									*
929| ************************************************************************/
930|
931|static int
932|xmlDetectEBCDIC(xmlParserInputPtr input, xmlCharEncodingHandlerPtr *hout) {
933|    xmlChar out[200];
934|    xmlCharEncodingHandlerPtr handler;
935|    int inlen, outlen, res, i;
936|
937|    *hout = NULL;
938|
939|    /*
940|     * To detect the EBCDIC code page, we convert the first 200 bytes
941|     * to EBCDIC-US and try to find the encoding declaration.
942|     */
943|    res = xmlLookupCharEncodingHandler(XML_CHAR_ENCODING_EBCDIC, &handler);
944|    if (res != 0)
945|        return(res);
946|    outlen = sizeof(out) - 1;
947|    inlen = input->end - input->cur;
948|    res = xmlEncInputChunk(handler, out, &outlen, input->cur, &inlen);
949|    /*
950|     * Return the EBCDIC handler if decoding failed. The error will
951|     * be reported later.
952|     */
953|    if (res < 0)
954|        goto done;
955|    out[outlen] = 0;
956|
957|    for (i = 0; i < outlen; i++) {
958|        if (out[i] == '>')
959|            break;
960|        if ((out[i] == 'e') &&
961|            (xmlStrncmp(out + i, BAD_CAST "encoding", 8) == 0)) {
962|            int start, cur, quote;
963|
964|            i += 8;
965|            while (IS_BLANK_CH(out[i]))
966|                i += 1;
967|            if (out[i++] != '=')
968|                break;
969|            while (IS_BLANK_CH(out[i]))
970|                i += 1;
971|            quote = out[i++];
972|            if ((quote != '\'') && (quote != '"'))
973|                break;
974|            start = i;
975|            cur = out[i];
976|            while (((cur >= 'a') && (cur <= 'z')) ||
977|                   ((cur >= 'A') && (cur <= 'Z')) ||
978|                   ((cur >= '0') && (cur <= '9')) ||
979|                   (cur == '.') || (cur == '_') ||
980|                   (cur == '-'))
981|                cur = out[++i];
982|            if (cur != quote)
983|                break;
984|            out[i] = 0;
985|            xmlCharEncCloseFunc(handler);
986|            res = xmlOpenCharEncodingHandler((char *) out + start,
987|                                             /* output */ 0, &handler);
988|            if (res != 0)
989|                return(res);
990|            *hout = handler;
991|            return(0);
992|        }
993|    }
994|
995|done:
996|    /*
997|     * Encoding handlers are stateful, so we have to recreate them.
998|     */
999|    xmlCharEncCloseFunc(handler);
1000|    res = xmlLookupCharEncodingHandler(XML_CHAR_ENCODING_EBCDIC, &handler);
1001|    if (res != 0)
1002|        return(res);
1003|    *hout = handler;
1004|    return(0);
1005|}
