1244|         */
1245|        if ((in[0] == 0xEF) && (in[1] == 0xBB) && (in[2] == 0xBF)) {
1246|            ctxt->input->cur += 3;
1247|        }
1248|
1249|        return;
1250|    }
1251|
1252|    enc = XML_CHAR_ENCODING_NONE;
1253|    bomSize = 0;
1254|
1255|    switch (in[0]) {
1256|        case 0x00:
1257|            if ((in[1] == 0x00) && (in[2] == 0x00) && (in[3] == 0x3C)) {
1258|                enc = XML_CHAR_ENCODING_UCS4BE;
1259|                autoFlag = XML_INPUT_AUTO_OTHER;
1260|            } else if ((in[1] == 0x3C) && (in[2] == 0x00) && (in[3] == 0x3F)) {
1261|                enc = XML_CHAR_ENCODING_UTF16BE;
1262|                autoFlag = XML_INPUT_AUTO_UTF16BE;
1263|            }
1264|            break;
1265|
1266|        case 0x3C:
1267|            if (in[1] == 0x00) {
1268|                if ((in[2] == 0x00) && (in[3] == 0x00)) {
1269|                    enc = XML_CHAR_ENCODING_UCS4LE;
1270|                    autoFlag = XML_INPUT_AUTO_OTHER;
1271|                } else if ((in[2] == 0x3F) && (in[3] == 0x00)) {
1272|                    enc = XML_CHAR_ENCODING_UTF16LE;
1273|                    autoFlag = XML_INPUT_AUTO_UTF16LE;
1274|                }
1275|            }
1276|            break;
1277|
1278|        case 0x4C:
1279|	    if ((in[1] == 0x6F) && (in[2] == 0xA7) && (in[3] == 0x94)) {
1280|	        enc = XML_CHAR_ENCODING_EBCDIC;
1281|                autoFlag = XML_INPUT_AUTO_OTHER;
1282|            }
1283|            break;
1284|
1285|        case 0xEF:
1286|            if ((in[1] == 0xBB) && (in[2] == 0xBF)) {
1287|                enc = XML_CHAR_ENCODING_UTF8;
1288|                autoFlag = XML_INPUT_AUTO_UTF8;
1289|                bomSize = 3;
1290|            }
1291|            break;
1292|
1293|        case 0xFE:
1294|            if (in[1] == 0xFF) {
1295|                enc = XML_CHAR_ENCODING_UTF16BE;
1296|                autoFlag = XML_INPUT_AUTO_UTF16BE;
1297|                bomSize = 2;
1298|            }
1299|            break;
1300|
1301|        case 0xFF:
1302|            if (in[1] == 0xFE) {
1303|                enc = XML_CHAR_ENCODING_UTF16LE;
1304|                autoFlag = XML_INPUT_AUTO_UTF16LE;
1305|                bomSize = 2;
1306|            }
1307|            break;
1308|    }
1309|
1310|    if (bomSize > 0) {
1311|        ctxt->input->cur += bomSize;
1312|    }
1313|
1314|    if (enc != XML_CHAR_ENCODING_NONE) {
1315|        ctxt->input->flags |= autoFlag;
1316|        xmlSwitchEncoding(ctxt, enc);
1317|    }
1318|}
