1320|/**
1321| * xmlSetDeclaredEncoding:
1322| * @ctxt:  the parser context
1323| * @encoding:  declared encoding
1324| *
1325| * Set the encoding from a declaration in the document.
1326| *
1327| * If no encoding was set yet, switch the encoding. Otherwise, only warn
1328| * about encoding mismatches.
1329| *
1330| * Takes ownership of 'encoding'.
1331| */
1332|void
1333|xmlSetDeclaredEncoding(xmlParserCtxtPtr ctxt, xmlChar *encoding) {
1334|    if (((ctxt->input->flags & XML_INPUT_HAS_ENCODING) == 0) &&
1335|        ((ctxt->options & XML_PARSE_IGNORE_ENC) == 0)) {
1336|        xmlSwitchEncodingName(ctxt, (const char *) encoding);
1337|        ctxt->input->flags |= XML_INPUT_USES_ENC_DECL;
1338|    } else if (ctxt->input->flags & XML_INPUT_AUTO_ENCODING) {
1339|        static const char *allowedUTF8[] = {
1340|            "UTF-8", "UTF8", NULL
1341|        };
1342|        static const char *allowedUTF16LE[] = {
1343|            "UTF-16", "UTF-16LE", "UTF16", NULL
1344|        };
1345|        static const char *allowedUTF16BE[] = {
1346|            "UTF-16", "UTF-16BE", "UTF16", NULL
1347|        };
1348|        const char **allowed = NULL;
1349|        const char *autoEnc = NULL;
1350|
1351|        switch (ctxt->input->flags & XML_INPUT_AUTO_ENCODING) {
1352|            case XML_INPUT_AUTO_UTF8:
1353|                allowed = allowedUTF8;
1354|                autoEnc = "UTF-8";
1355|                break;
1356|            case XML_INPUT_AUTO_UTF16LE:
1357|                allowed = allowedUTF16LE;
1358|                autoEnc = "UTF-16LE";
1359|                break;
1360|            case XML_INPUT_AUTO_UTF16BE:
1361|                allowed = allowedUTF16BE;
1362|                autoEnc = "UTF-16BE";
1363|                break;
1364|        }
1365|
1366|        if (allowed != NULL) {
1367|            const char **p;
1368|            int match = 0;
1369|
1370|            for (p = allowed; *p != NULL; p++) {
1371|                if (xmlStrcasecmp(encoding, BAD_CAST *p) == 0) {
1372|                    match = 1;
1373|                    break;
1374|                }
1375|            }
1376|
1377|            if (match == 0) {
1378|                xmlWarningMsg(ctxt, XML_WAR_ENCODING_MISMATCH,
1379|                              "Encoding '%s' doesn't match "
1380|                              "auto-detected '%s'\n",
1381|                              encoding, BAD_CAST autoEnc);
1382|                xmlFree(encoding);
1383|                encoding = xmlStrdup(BAD_CAST autoEnc);
1384|                if (encoding == NULL)
1385|                    xmlCtxtErrMemory(ctxt);
1386|            }
1387|        }
1388|    }
1389|
1390|    if (ctxt->encoding != NULL)
1391|        xmlFree((xmlChar *) ctxt->encoding);
1392|    ctxt->encoding = encoding;
1393|}
