1855|/**
1856| * xmlResolveResourceFromCatalog:
1857| * @URL:  the URL for the entity to load
1858| * @ID:  the System ID for the entity to load
1859| * @ctxt:  the context in which the entity is called or NULL
1860| *
1861| * Resolves the URL and ID against the appropriate catalog.
1862| * This function is used by xmlDefaultExternalEntityLoader and
1863| * xmlNoNetExternalEntityLoader.
1864| *
1865| * Returns a new allocated URL, or NULL.
1866| */
1867|static xmlChar *
1868|xmlResolveResourceFromCatalog(const char *URL, const char *ID,
1869|                              xmlParserCtxtPtr ctxt) {
1870|    xmlChar *resource = NULL;
1871|    xmlCatalogAllow pref;
1872|
1873|    /*
1874|     * If the resource doesn't exists as a file,
1875|     * try to load it from the resource pointed in the catalogs
1876|     */
1877|    pref = xmlCatalogGetDefaults();
1878|
1879|    if ((pref != XML_CATA_ALLOW_NONE) && (!xmlNoNetExists(URL))) {
1880|	/*
1881|	 * Do a local lookup
1882|	 */
1883|	if ((ctxt != NULL) && (ctxt->catalogs != NULL) &&
1884|	    ((pref == XML_CATA_ALLOW_ALL) ||
1885|	     (pref == XML_CATA_ALLOW_DOCUMENT))) {
1886|	    resource = xmlCatalogLocalResolve(ctxt->catalogs,
1887|					      (const xmlChar *)ID,
1888|					      (const xmlChar *)URL);
1889|        }
1890|	/*
1891|	 * Try a global lookup
1892|	 */
1893|	if ((resource == NULL) &&
1894|	    ((pref == XML_CATA_ALLOW_ALL) ||
1895|	     (pref == XML_CATA_ALLOW_GLOBAL))) {
1896|	    resource = xmlCatalogResolve((const xmlChar *)ID,
1897|					 (const xmlChar *)URL);
1898|	}
1899|	if ((resource == NULL) && (URL != NULL))
