2602|/**
2603| * xmlParserFindNodeInfoIndex:
2604| * @seq:  a node info sequence pointer
2605| * @node:  an XML node pointer
2606| *
2607| * DEPRECATED: Don't use.
2608| *
2609| * xmlParserFindNodeInfoIndex : Find the index that the info record for
2610| *   the given node is or should be at in a sorted sequence
2611| *
2612| * Returns a long indicating the position of the record
2613| */
2614|unsigned long
2615|xmlParserFindNodeInfoIndex(xmlParserNodeInfoSeqPtr seq,
2616|                           xmlNodePtr node)
2617|{
2618|    unsigned long upper, lower, middle;
2619|    int found = 0;
2620|
2621|    if ((seq == NULL) || (node == NULL))
2622|        return ((unsigned long) -1);
2623|
2624|    /* Do a binary search for the key */
2625|    lower = 1;
2626|    upper = seq->length;
2627|    middle = 0;
2628|    while (lower <= upper && !found) {
2629|        middle = lower + (upper - lower) / 2;
2630|        if (node == seq->buffer[middle - 1].node)
2631|            found = 1;
2632|        else if (node < seq->buffer[middle - 1].node)
2633|            upper = middle - 1;
2634|        else
2635|            lower = middle + 1;
2636|    }
2637|
2638|    /* Return position */
2639|    if (middle == 0 || seq->buffer[middle - 1].node < node)
2640|        return middle;
2641|    else
2642|        return middle - 1;
2643|}
