2646|/**
2647| * xmlParserAddNodeInfo:
2648| * @ctxt:  an XML parser context
2649| * @info:  a node info sequence pointer
2650| *
2651| * DEPRECATED: Don't use.
2652| *
2653| * Insert node info record into the sorted sequence
2654| */
2655|void
2656|xmlParserAddNodeInfo(xmlParserCtxtPtr ctxt,
2657|                     xmlParserNodeInfoPtr info)
2658|{
2659|    unsigned long pos;
2660|
2661|    if ((ctxt == NULL) || (info == NULL)) return;
2662|
2663|    /* Find pos and check to see if node is already in the sequence */
2664|    pos = xmlParserFindNodeInfoIndex(&ctxt->node_seq, (xmlNodePtr)
2665|                                     info->node);
2666|
2667|    if ((pos < ctxt->node_seq.length) &&
2668|        (ctxt->node_seq.buffer != NULL) &&
2669|        (ctxt->node_seq.buffer[pos].node == info->node)) {
2670|        ctxt->node_seq.buffer[pos] = *info;
2671|    }
2672|
2673|    /* Otherwise, we need to add new node to buffer */
2674|    else {
2675|        if ((ctxt->node_seq.length + 1 > ctxt->node_seq.maximum) ||
2676|	    (ctxt->node_seq.buffer == NULL)) {
2677|            xmlParserNodeInfo *tmp_buffer;
2678|            unsigned int byte_size;
2679|
2680|            if (ctxt->node_seq.maximum == 0)
2681|                ctxt->node_seq.maximum = 2;
2682|            byte_size = (sizeof(*ctxt->node_seq.buffer) *
2683|			(2 * ctxt->node_seq.maximum));
2684|
2685|            if (ctxt->node_seq.buffer == NULL)
2686|                tmp_buffer = (xmlParserNodeInfo *) xmlMalloc(byte_size);
2687|            else
2688|                tmp_buffer =
2689|                    (xmlParserNodeInfo *) xmlRealloc(ctxt->node_seq.buffer,
2690|                                                     byte_size);
2691|
2692|            if (tmp_buffer == NULL) {
2693|		xmlCtxtErrMemory(ctxt);
2694|                return;
2695|            }
2696|            ctxt->node_seq.buffer = tmp_buffer;
2697|            ctxt->node_seq.maximum *= 2;
2698|        }
2699|
2700|        /* If position is not at end, move elements out of the way */
2701|        if (pos != ctxt->node_seq.length) {
2702|            unsigned long i;
2703|
2704|            for (i = ctxt->node_seq.length; i > pos; i--)
2705|                ctxt->node_seq.buffer[i] = ctxt->node_seq.buffer[i - 1];
2706|        }
2707|
2708|        /* Copy element and increase length */
2709|        ctxt->node_seq.buffer[pos] = *info;
2710|        ctxt->node_seq.length++;
2711|    }
2712|}
